function y({registerIndicator:m,sourceValues:f,nulls:p}){m({id:"oa-trima",name:"Triangular Moving Average (TRIMA)",category:"Trends FIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"trima",type:"line",title:"TRIMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(i,l){const d=Math.max(1,Math.floor(Number(l.period)||10)),o=f(i,l.source??"close"),r=new Array(i.length).fill(NaN);for(let e=0;e<i.length;e++){const a=Math.min(e+1,d),h=a-1;let c=0,n=0;for(let t=0;t<a;t++){const s=o[e-t];if(!Number.isFinite(s))continue;const u=Math.min(t,h-t)+1;c+=s*u,n+=u}n>0?r[e]=c/n:Number.isFinite(o[e])&&(r[e]=o[e])}return{trima:p(r)}}})}export{y as default};
